changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_analysis_analyzer_completed
    ON clinlims.analysis (analyzer_id, completed_date) WHERE analyzer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_analyzer_delivery_receipt_analyzer_accepted
    ON clinlims.analyzer_delivery_receipt (analyzer_id, accepted_at);
CREATE INDEX IF NOT EXISTS idx_analyzer_event_analyzer_received
    ON clinlims.analyzer_event (analyzer_id, received_at);
CREATE INDEX IF NOT EXISTS idx_analyzer_results_analyzer_updated
    ON clinlims.analyzer_results (analyzer_id, last_updated);

rollback.sql:
DROP INDEX IF EXISTS clinlims.idx_analysis_analyzer_completed;
DROP INDEX IF EXISTS clinlims.idx_analyzer_delivery_receipt_analyzer_accepted;
DROP INDEX IF EXISTS clinlims.idx_analyzer_event_analyzer_received;
DROP INDEX IF EXISTS clinlims.idx_analyzer_results_analyzer_updated;
